import fs from 'node:fs';
import {mini,mini2ast} from './node_modules/@strudel/mini/dist/index.mjs';
import {note,noteToMidi,Fraction} from './node_modules/@strudel/core/dist/index.mjs';
import {transpiler} from './node_modules/@strudel/transpiler/dist/index.mjs';
const frac=x=>x.toFraction();
const out=[];
for(const provider of ['openai','gemini']){
 const run=JSON.parse(fs.readFileSync(`${process.cwd()}/brain/benchmarks/native-composite-v1/runs/${provider}.json`));
 for(const row of run.results.filter(r=>r.arm==='strudel-v1.2-native'&&r.repeat===1&&r.family!=='comprehension-analysis')){
  const text=row.initial_call.response_payload; const record={provider,planned_sequence:row.planned_sequence,notes:[],lines:[],javascript_valid:false};
  try{
   transpiler(text);record.javascript_valid=true;
   for(const line of text.split('\n').slice(1)){
    const m=line.match(/^([a-z]+)_([0-9]+): note\("([^"]+)"\)\.slow\(([^)]+)\)\.sound\("piano"\)$/);if(!m)throw Error('unexpected line');
    const slow=m[4].split('/').map(Number).reduce((a,b)=>a/b);const p=note(mini(m[3])).slow(slow).sound(mini('piano')); const haps=p.queryArc(0,slow);
    const fragments=haps.map(h=>({voice:m[1],start:frac(h.whole.begin.mul(4)),duration:frac(h.whole.end.sub(h.whole.begin).mul(4)),pitch:typeof h.value.note==='number'?h.value.note:noteToMidi(h.value.note)}));
    const notes=Array.from(new Map(fragments.map(n=>[JSON.stringify(n),n])).values());
    record.notes.push(...notes);record.lines.push({line,ast:mini2ast(JSON.stringify(m[3])),decoded:notes,whole_event_count:notes.length,fragment_count:haps.length,period_beats:frac(Fraction(slow).mul(4))});
   }
   record.engine_valid=true;
  }catch(e){record.engine_valid=false;record.error=String(e);}
  out.push(record);
 }
}
fs.writeFileSync('/private/tmp/ghostnote-strudel-full-grammar/decoded.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out.map(r=>({provider:r.provider,sequence:r.planned_sequence,valid:r.engine_valid,count:r.notes.length,error:r.error}))));
